// AscendC GroupNormSwish kernel
// Fused Group Normalization + Swish activation
// Supports float32, float16, bfloat16

#include "kernel_operator.h"
#include <cmath>

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t BLOCK_INNER = 1024;

// ---------------------------------------------------------------------------
// Inline helpers
// ---------------------------------------------------------------------------

__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
{
    if (b == 0U) { return 0U; }
    return (a + b - 1U) / b;
}

template <typename T>
__aicore__ inline void LoadGmToUb(
    AscendC::LocalTensor<T> &dst,
    AscendC::GlobalTensor<T> src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
    AscendC::DataCopyPad(dst, src, copyParams, padParams);
}

template <typename T>
__aicore__ inline void StoreUbToGm(
    AscendC::GlobalTensor<T> dst,
    AscendC::LocalTensor<T> &src,
    uint32_t count)
{
    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
    AscendC::DataCopyPad(dst, src, copyParams);
}

template <typename T>
__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
{
    if constexpr (std::is_same_v<T, bfloat16_t>) {
        return AscendC::RoundMode::CAST_ROUND;
    }
    return AscendC::RoundMode::CAST_NONE;
}

template <typename T>
__aicore__ inline void PrepareInputTensorHelper(
    AscendC::LocalTensor<float> &dst,
    AscendC::LocalTensor<T> &src,
    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
    int32_t count)
{
    if constexpr (std::is_same_v<T, float>) {
        dst = src.template ReinterpretCast<float>();
    } else {
        dst = castBuf.Get<float>();
        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

template <typename T>
__aicore__ inline void FinalizeOutputTensorHelper(
    AscendC::LocalTensor<T> &out,
    AscendC::LocalTensor<float> &src,
    int32_t count)
{
    if constexpr (!std::is_same_v<T, float>) {
        AscendC::Cast(out, src, OutputRoundModeHelper<T>(), count);
        AscendC::PipeBarrier<PIPE_V>();
    }
}

// =========================================================================
// GroupNormSwish Kernel
// =========================================================================

template <typename dataType>
class GroupNormSwishKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR x, GM_ADDR weight, GM_ADDR bias,
        GM_ADDR y, GM_ADDR meanOut, GM_ADDR rstdOut,
        int32_t N, int32_t C, int32_t innerSpatial, int32_t numGroups,
        int32_t innerDim, int32_t cpg, int32_t totalTasks,
        int32_t tasksPerCore, int32_t blockInner,
        float eps, float swishScale)
    {
        this->N = N;
        this->C = C;
        this->innerSpatial = innerSpatial;
        this->numGroups = numGroups;
        this->innerDim = innerDim;
        this->cpg = cpg;
        this->totalTasks = totalTasks;
        this->tasksPerCore = tasksPerCore;
        this->blockInner = blockInner;
        this->eps = eps;
        this->swishScale = swishScale;

        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x),
            static_cast<uint64_t>(N) * C * innerSpatial);
        weightGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(weight), C);
        biasGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(bias), C);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(y),
            static_cast<uint64_t>(N) * C * innerSpatial);
        meanGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(meanOut),
            static_cast<uint64_t>(N) * numGroups);
        rstdGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(rstdOut),
            static_cast<uint64_t>(N) * numGroups);

        if ASCEND_IS_AIV { InitAivBuffers(); }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx();
            for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
                const int taskIdx = coreIdx * tasksPerCore + localIdx;
                if (taskIdx >= totalTasks) {
                    continue;
                }
                ProcessOneTask(taskIdx);
            }
        }
    }

private:
    __aicore__ inline void InitAivBuffers()
    {
        pipe.InitBuffer(xInQueue_, BUFFER_NUM, blockInner * sizeof(dataType));
        pipe.InitBuffer(yOutQueue_, BUFFER_NUM, blockInner * sizeof(dataType));
        pipe.InitBuffer(reduceBuf_, blockInner * sizeof(float));
        pipe.InitBuffer(computeBuf1_, blockInner * sizeof(float));
        pipe.InitBuffer(computeBuf2_, blockInner * sizeof(float));
        pipe.InitBuffer(computeBuf3_, blockInner * sizeof(float));
        pipe.InitBuffer(sumBuf_, 16 * sizeof(float));
        pipe.InitBuffer(scalarBuf_, 4 * sizeof(float));
        if constexpr (!std::is_same_v<dataType, float>) {
            pipe.InitBuffer(xCastBuf_, blockInner * sizeof(float));
            pipe.InitBuffer(yCastBuf_, blockInner * sizeof(float));
        }
    }

    // -----------------------------------------------------------------------
    // CopyIn / CopyOut helpers
    // -----------------------------------------------------------------------

    __aicore__ inline void CopyInX(uint64_t gmOffset, int32_t count)
    {
        xInLocal_ = xInQueue_.AllocTensor<dataType>();
        LoadGmToUb(xInLocal_, xGM_[gmOffset], static_cast<uint32_t>(count));
        xInQueue_.EnQue(xInLocal_);
    }

    __aicore__ inline void CopyOutY(uint64_t gmOffset, int32_t count)
    {
        yOutLocal_ = yOutQueue_.DeQue<dataType>();
        StoreUbToGm(yGM_[gmOffset], yOutLocal_, static_cast<uint32_t>(count));
        yOutQueue_.FreeTensor(yOutLocal_);
    }

    __aicore__ inline void CopyOutScalar(
        AscendC::GlobalTensor<dataType> &gmDst,
        uint64_t gmOffset,
        AscendC::LocalTensor<float> &srcFloat)
    {
        AscendC::LocalTensor<dataType> dstLocal;
        if constexpr (std::is_same_v<dataType, float>) {
            dstLocal = srcFloat.template ReinterpretCast<dataType>();
        } else {
            dstLocal = scalarBuf_.Get<dataType>();
            AscendC::Cast(dstLocal, srcFloat, OutputRoundModeHelper<dataType>(), 1);
            AscendC::PipeBarrier<PIPE_V>();
        }
        StoreUbToGm(gmDst[gmOffset], dstLocal, 1);
    }

    // -----------------------------------------------------------------------
    // Pass 1: compute sum and sum_sq over inner_dim
    // -----------------------------------------------------------------------

    __aicore__ inline void Pass1SumSq(uint64_t groupBase, float &sum, float &sumSq)
    {
        sum = 0.0f;
        sumSq = 0.0f;

        int32_t numTiles = (innerDim + blockInner - 1) / blockInner;
        reduceLocal_ = reduceBuf_.Get<float>();
        sumLocal_ = sumBuf_.Get<float>();

        for (int32_t t = 0; t < numTiles; ++t) {
            int32_t offset = t * blockInner;
            int32_t curCount = (offset + blockInner <= innerDim) ? blockInner : (innerDim - offset);

            CopyInX(groupBase + offset, curCount);

            xInLocal_ = xInQueue_.DeQue<dataType>();
            PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, curCount);

            // Compute x^2
            computeLocal1_ = computeBuf1_.Get<float>();
            AscendC::Mul(computeLocal1_, xLocal_, xLocal_, curCount);

            // Reduce sum over x
            AscendC::ReduceSum<float>(sumLocal_, xLocal_, reduceLocal_, curCount);
            sum += sumLocal_.GetValue(0);

            // Reduce sum_sq over x^2
            AscendC::ReduceSum<float>(sumLocal_, computeLocal1_, reduceLocal_, curCount);
            sumSq += sumLocal_.GetValue(0);

            xInQueue_.FreeTensor(xInLocal_);
        }
    }

    // -----------------------------------------------------------------------
    // Pass 2: normalize + weight/bias + swish + output
    // -----------------------------------------------------------------------

    __aicore__ inline void Pass2Apply(
        uint64_t groupBase, int32_t wgtBase, float meanVal, float rstdVal)
    {
        // Iterate over channels in the group
        for (int32_t ch = 0; ch < cpg; ++ch) {
            uint64_t chBase = groupBase + static_cast<uint64_t>(ch) * innerSpatial;
            int32_t chWeight = wgtBase + ch;

            // Load weight and bias for this channel as scalar
            AscendC::DataCopyExtParams scalarCopyParams{1, sizeof(dataType), 0, 0, 0};
            AscendC::DataCopyPadExtParams<dataType> scalarPadParams{true, 0, 0, static_cast<dataType>(0)};

            AscendC::LocalTensor<dataType> wgtLocal = scalarBuf_.Get<dataType>();
            AscendC::DataCopyPad(wgtLocal, weightGM_[chWeight], scalarCopyParams, scalarPadParams);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            float wgtVal = static_cast<float>(wgtLocal.GetValue(0));
            AscendC::PipeBarrier<PIPE_ALL>();

            AscendC::LocalTensor<dataType> biasLocal = scalarBuf_.Get<dataType>();
            AscendC::DataCopyPad(biasLocal, biasGM_[chWeight], scalarCopyParams, scalarPadParams);
            AscendC::PipeBarrier<PIPE_MTE2>();
            AscendC::PipeBarrier<PIPE_ALL>();
            float biasVal = static_cast<float>(biasLocal.GetValue(0));
            AscendC::PipeBarrier<PIPE_ALL>();

            // Tile over spatial positions
            int32_t numSpatialTiles = (innerSpatial + blockInner - 1) / blockInner;

            for (int32_t st = 0; st < numSpatialTiles; ++st) {
                int32_t spOffset = st * blockInner;
                int32_t curCount = (spOffset + blockInner <= innerSpatial) ? blockInner : (innerSpatial - spOffset);

                CopyInX(chBase + spOffset, curCount);

                xInLocal_ = xInQueue_.DeQue<dataType>();
                PrepareInputTensorHelper<dataType>(xLocal_, xInLocal_, xCastBuf_, curCount);

                // Allocate output buffer
                yOutLocal_ = yOutQueue_.AllocTensor<dataType>();

                // Compute: norm = (x - mean) * rstd
                // = x * rstd - mean * rstd
                computeLocal1_ = computeBuf1_.Get<float>();
                AscendC::Muls(computeLocal1_, xLocal_, rstdVal, curCount);
                AscendC::Adds(computeLocal1_, computeLocal1_, -meanVal * rstdVal, curCount);

                // Apply weight and bias: norm = norm * weight + bias
                AscendC::Muls(computeLocal1_, computeLocal1_, wgtVal, curCount);
                AscendC::Adds(computeLocal1_, computeLocal1_, biasVal, curCount);

                // Swish activation: y = x * sigmoid(scale * x)
                // sigmoid is available as vector op
                computeLocal2_ = computeBuf2_.Get<float>();
                computeLocal3_ = computeBuf3_.Get<float>();

                // sigmoid_in = swishScale * norm
                AscendC::Muls(computeLocal2_, computeLocal1_, swishScale, curCount);
                // sigmoid(computeLocal2_)
                AscendC::Sigmoid(computeLocal3_, computeLocal2_, curCount);
                // swish = norm * sigmoid
                AscendC::Mul(computeLocal1_, computeLocal1_, computeLocal3_, curCount);

                // Finalize output: cast if needed
                if constexpr (std::is_same_v<dataType, float>) {
                    yOutLocal_ = computeLocal1_.template ReinterpretCast<dataType>();
                } else {
                    AscendC::Cast(yOutLocal_, computeLocal1_, OutputRoundModeHelper<dataType>(), curCount);
                    AscendC::PipeBarrier<PIPE_V>();
                }

                yOutQueue_.EnQue(yOutLocal_);
                xInQueue_.FreeTensor(xInLocal_);

                // CopyOut
                CopyOutY(chBase + spOffset, curCount);
            }
        }
    }

    // -----------------------------------------------------------------------
    // Process one (N, group) task
    // -----------------------------------------------------------------------

    __aicore__ inline void ProcessOneTask(int32_t taskIdx)
    {
        int32_t n = taskIdx / numGroups;
        int32_t g = taskIdx % numGroups;

        // Compute group base offset in flattened [N, C, innerSpatial] layout
        uint64_t groupBase = static_cast<uint64_t>(n) * C * innerSpatial +
                             static_cast<uint64_t>(g) * cpg * innerSpatial;
        int32_t wgtBase = g * cpg;

        // Pass 1: compute sum and sum_sq over all inner_dim elements
        float sumVal, sumSqVal;
        Pass1SumSq(groupBase, sumVal, sumSqVal);

        // Compute statistics
        float invDim = 1.0f / static_cast<float>(innerDim);
        float meanVal = sumVal * invDim;
        float varVal = sumSqVal * invDim - meanVal * meanVal;
        if (varVal < 0.0f) { varVal = 0.0f; }
        float rstdVal = 1.0f / ::sqrt(varVal + eps);

        // Write mean and rstd outputs
        AscendC::LocalTensor<float> meanFloat = sumBuf_.Get<float>();
        AscendC::LocalTensor<float> rstdFloat = scalarBuf_.Get<float>();
        meanFloat.SetValue(0, meanVal);
        rstdFloat.SetValue(0, rstdVal);
        AscendC::PipeBarrier<PIPE_V>();

        CopyOutScalar(meanGM_, static_cast<uint64_t>(n) * numGroups + g, meanFloat);
        CopyOutScalar(rstdGM_, static_cast<uint64_t>(n) * numGroups + g, rstdFloat);

        // Pass 2: normalize + weight/bias + swish + output
        Pass2Apply(groupBase, wgtBase, meanVal, rstdVal);
    }

private:
    int32_t N = 0;
    int32_t C = 0;
    int32_t innerSpatial = 0;
    int32_t numGroups = 0;
    int32_t innerDim = 0;
    int32_t cpg = 0;
    int32_t totalTasks = 0;
    int32_t tasksPerCore = 0;
    int32_t blockInner = BLOCK_INNER;
    float eps = 0.0f;
    float swishScale = 0.0f;

    AscendC::TPipe pipe;
    AscendC::GlobalTensor<dataType> xGM_;
    AscendC::GlobalTensor<dataType> weightGM_;
    AscendC::GlobalTensor<dataType> biasGM_;
    AscendC::GlobalTensor<dataType> yGM_;
    AscendC::GlobalTensor<dataType> meanGM_;
    AscendC::GlobalTensor<dataType> rstdGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> xInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> yOutQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> reduceBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf1_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf2_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> computeBuf3_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> sumBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> scalarBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> xCastBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;

    AscendC::LocalTensor<dataType> xInLocal_;
    AscendC::LocalTensor<dataType> yOutLocal_;
    AscendC::LocalTensor<float> xLocal_;
    AscendC::LocalTensor<float> computeLocal1_;
    AscendC::LocalTensor<float> computeLocal2_;
    AscendC::LocalTensor<float> computeLocal3_;
    AscendC::LocalTensor<float> reduceLocal_;
    AscendC::LocalTensor<float> sumLocal_;
};

// =========================================================================
// dtype dispatch helper
// =========================================================================

__aicore__ inline void DispatchGroupNormSwish(
    GM_ADDR x, GM_ADDR weight, GM_ADDR bias,
    GM_ADDR y, GM_ADDR mean, GM_ADDR rstd,
    int32_t N, int32_t C, int32_t innerSpatial, int32_t numGroups,
    int32_t innerDim, int32_t cpg, int32_t totalTasks,
    int32_t tasksPerCore, int32_t blockInner,
    float eps, float swishScale,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        GroupNormSwishKernel<float> kernel;
        kernel.Init(x, weight, bias, y, mean, rstd,
                    N, C, innerSpatial, numGroups,
                    innerDim, cpg, totalTasks, tasksPerCore, blockInner,
                    eps, swishScale);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        GroupNormSwishKernel<half> kernel;
        kernel.Init(x, weight, bias, y, mean, rstd,
                    N, C, innerSpatial, numGroups,
                    innerDim, cpg, totalTasks, tasksPerCore, blockInner,
                    eps, swishScale);
        kernel.Process();
    } else {
        GroupNormSwishKernel<bfloat16_t> kernel;
        kernel.Init(x, weight, bias, y, mean, rstd,
                    N, C, innerSpatial, numGroups,
                    innerDim, cpg, totalTasks, tasksPerCore, blockInner,
                    eps, swishScale);
        kernel.Process();
    }
}

// =========================================================================
// Kernel entry point
// dtypeFlag: 0=fp32, 1=fp16, 2=bf16
// =========================================================================

