#include "kernel_operator.h"

template <typename T>
class MinKernel {
public:
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, int32_t c) {
        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), c);
        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), c);
        if ASCEND_IS_AIV {
            pipe.InitBuffer(inQ_, 1, 64 * sizeof(T));
            pipe.InitBuffer(outQ_, 1, 64 * sizeof(T));
            pipe.InitBuffer(compBuf_, 64 * sizeof(float));
        }
    }
    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            auto inL = inQ_.AllocTensor<T>();
            AscendC::DataCopyExtParams cp{1, 64 * sizeof(T), 0, 0, 0};
            AscendC::DataCopyPadExtParams<T> pp{true, 0, 0, static_cast<T>(0)};
            AscendC::DataCopyPad(inL, xGM_[0], cp, pp);
            inQ_.EnQue(inL);

            inL = inQ_.DeQue<T>();
            auto outL = outQ_.AllocTensor<T>();

            auto fbuf = compBuf_.Get<float>();
            // No Cast! Just copy
            AscendC::DataCopyPad(yGM_[0], inL, cp);

            inQ_.FreeTensor(inL);
            outQ_.EnQue(outL);
        }
    }
private:
    AscendC::TPipe pipe;
    AscendC::GlobalTensor<T> xGM_, yGM_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQ_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQ_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> compBuf_;
};

__aicore__ inline void dispatch(GM_ADDR x, GM_ADDR y, int32_t c, int64_t flag) {
    if (flag == 2) {
        MinKernel<bfloat16_t> k; k.Init(x, y, c); k.Process();
    } else if (flag == 1) {
        MinKernel<half> k; k.Init(x, y, c); k.Process();
    } else {
        MinKernel<float> k; k.Init(x, y, c); k.Process();
    }
}

extern "C" __global__ __aicore__ void test_min(GM_ADDR x, GM_ADDR y, int32_t c, int64_t flag) {
    dispatch(x, y, c, flag);
}
