// GroupNormSwish op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_group_norm_swish.h"

constexpr int32_t BLOCK_INNER = 1024;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

namespace ascend_kernel {

std::vector<at::Tensor> group_norm_swish(
    const at::Tensor &input,
    int64_t numGroups,
    const at::Tensor &weight,
    const at::Tensor &bias,
    double eps,
    double swishScale)
{
    TORCH_CHECK(input.dim() >= 2, "input must have at least 2 dimensions");
    TORCH_CHECK(weight.dim() == 1, "weight must be 1D");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
    TORCH_CHECK(
        input.scalar_type() == at::kFloat || input.scalar_type() == at::kHalf ||
            input.scalar_type() == at::kBFloat16,
        "input must be float16, float32, or bfloat16");
    TORCH_CHECK(weight.scalar_type() == input.scalar_type(),
        "weight must have same dtype as input");
    TORCH_CHECK(bias.scalar_type() == input.scalar_type(),
        "bias must have same dtype as input");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");

    // Handle bf16 by converting to fp16 (AIV compiler doesn't support bf16 Cast)
    bool isBf16 = (input.scalar_type() == at::kBFloat16);
    at::Tensor inputFp16, weightFp16, biasFp16;
    if (isBf16) {
        inputFp16 = input.to(at::kHalf);
        weightFp16 = weight.to(at::kHalf);
        biasFp16 = bias.to(at::kHalf);
    }

    const at::Tensor &inRef = isBf16 ? inputFp16 : input;
    const at::Tensor &wRef = isBf16 ? weightFp16 : weight;
    const at::Tensor &bRef = isBf16 ? biasFp16 : bias;

    // Extract dimensions
    int32_t N = static_cast<int32_t>(inRef.sizes()[0]);
    int32_t C = static_cast<int32_t>(inRef.sizes()[1]);
    int32_t innerSpatial = 1;
    for (int64_t d = 2; d < inRef.dim(); ++d) {
        innerSpatial *= static_cast<int32_t>(inRef.sizes()[d]);
    }

    int32_t numGroups32 = static_cast<int32_t>(numGroups);
    TORCH_CHECK(C % numGroups32 == 0, "C must be divisible by num_groups");
    int32_t cpg = C / numGroups32;
    int32_t innerDim = cpg * innerSpatial;

    TORCH_CHECK(static_cast<int32_t>(wRef.sizes()[0]) == C, "weight size must equal C");
    TORCH_CHECK(static_cast<int32_t>(bRef.sizes()[0]) == C, "bias size must equal C");

    // Compute tiling
    int32_t totalTasks = N * numGroups32;
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t usedCoreNum = std::min<int32_t>(
        static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv()),
        std::max<int32_t>(1, totalTasks));
    int32_t tasksPerCore = (totalTasks + usedCoreNum - 1) / usedCoreNum;

    // Allocate output tensors (in original dtype for bf16 case, or fp16/fp32)
    at::Tensor yFp16, meanFp16, rstdFp16;
    if (isBf16) {
        yFp16 = at::empty_like(inputFp16);
        meanFp16 = at::empty({N, numGroups32}, at::dtype(at::kHalf).device(input.device()));
        rstdFp16 = at::empty({N, numGroups32}, at::dtype(at::kHalf).device(input.device()));
    }
    at::Tensor y = isBf16 ? yFp16 : at::empty_like(inRef);
    at::Tensor meanOut = isBf16 ? meanFp16 :
        at::empty({N, numGroups32}, inRef.options());
    at::Tensor rstdOut = isBf16 ? rstdFp16 :
        at::empty({N, numGroups32}, inRef.options());

    // dtype flag: 0=fp32, 1=fp16 (bf16 is mapped to fp16)
    int64_t dtypeFlag = (inRef.scalar_type() == at::kHalf) ? 1 : 0;

    // All EXEC_KERNEL_CMD parameters must be left values
    float epsVal = static_cast<float>(eps);
    float swishScaleVal = static_cast<float>(swishScale);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int32_t blockInner = BLOCK_INNER;

    EXEC_KERNEL_CMD(group_norm_swish, blockDim,
                    inRef, wRef, bRef, y, meanOut, rstdOut,
                    N, C, innerSpatial, numGroups32,
                    innerDim, cpg, totalTasks, tasksPerCore, blockInner,
                    epsVal, swishScaleVal,
                    dtypeFlag);

    // Convert back to bf16 if needed
    if (isBf16) {
        return {y.to(at::kBFloat16), meanOut.to(at::kBFloat16), rstdOut.to(at::kBFloat16)};
    }
    return {y, meanOut, rstdOut};
}

}  // namespace ascend_kernel
